using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace RestApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API (JSONPlaceholder as an example).
/// Uses constructor injection for HttpClient and ILogger.
/// </summary>
[McpServerToolType]
public class UserApiTools(HttpClient httpClient, ILogger<UserApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get a user by their numeric ID from the REST API.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID (1-10)")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var response = await httpClient.GetAsync($"/users/{userId}", cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool, Description("List all users from the REST API.")]
    public async Task<string> ListUsers(CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing all users");
        var response = await httpClient.GetAsync("/users", cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool, Description("Search for posts by a specific user.")]
    public async Task<string> GetUserPosts(
        [Description("The numeric user ID whose posts to retrieve")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching posts for user {UserId}", userId);
        var response = await httpClient.GetAsync($"/users/{userId}/posts", cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool, Description("Create a new post for a user.")]
    public async Task<string> CreatePost(
        [Description("The user ID authoring the post")] int userId,
        [Description("The title of the post")] string title,
        [Description("The body content of the post")] string body,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var payload = new { userId, title, body };
        var content = new StringContent(
            JsonSerializer.Serialize(payload),
            System.Text.Encoding.UTF8,
            "application/json");

        var response = await httpClient.PostAsync("/posts", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }
}

